"use strict";
// sg-home.com: a demo property portal. Hash-routed single page; data from /data/*.json
// (generated by generate.py) and /api/* (app.py, backed by the sg-homes models).

const SQFT = 10.7639;
const PAGE = 18;
const KIND_NAME = { hdb: "HDB", condo: "Condo", landed: "Landed" };
const KIND_COLOR = { hdb: "#2a78d6", condo: "#eb6834", landed: "#1baf7a" };
const MAP_STYLE = "https://basemaps.cartocdn.com/gl/positron-gl-style/style.json";
const S = { listings: [], byId: {}, meta: null, agents: {}, projects: [], projById: {}, trends: null, forecast: null };

// ---------- storage (per-viewer conveniences only) ----------
const store = {
  get(k, d) { try { const v = localStorage.getItem("lorong:" + k); return v ? JSON.parse(v) : d; } catch { return d; } },
  set(k, v) { try { localStorage.setItem("lorong:" + k, JSON.stringify(v)); } catch { /* storage unavailable */ } },
};
const shortlist = new Set(store.get("shortlist", []));
let compare = store.get("compare", []);
let savedSearches = store.get("searches", []);
// Random per-browser ID so "Your enquiries" only shows enquiries sent from this browser.
const CLIENT_ID = store.get("client", null) || (() => {
  const id = [...crypto.getRandomValues(new Uint8Array(16))].map(b => b.toString(16).padStart(2, "0")).join("");
  store.set("client", id);
  return id;
})();

// ---------- helpers ----------
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const fmt$ = v => "$" + Math.round(v).toLocaleString("en-SG");
const fmtK = v => v >= 1e6 ? "$" + (v / 1e6).toFixed(v >= 1e7 ? 1 : 2) + "M" : "$" + Math.round(v / 1e3) + "k";
const title = s => String(s ?? "").toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
const priceText = l => l.mode === "rent" ? `${fmt$(l.price)}<small> /mo</small>` : fmt$(l.price);
const psfText = l => l.mode === "rent" ? `$${l.psf.toFixed(2)} psf/mo` : `$${Math.round(l.psf).toLocaleString("en-SG")} psf`;
const qsParse = s => Object.fromEntries(new URLSearchParams(s));
const qsBuild = o => new URLSearchParams(Object.entries(o).filter(([, v]) => v !== "" && v != null)).toString();
const daysAgo = iso => Math.max(0, Math.round((Date.now() - new Date(iso)) / 864e5));
const ago = iso => { const d = daysAgo(iso); return d === 0 ? "today" : d === 1 ? "1 day ago" : `${d} days ago`; };
function haversine(a, b) {
  const R = 6371e3, r = Math.PI / 180;
  const x = Math.sin((b.lat - a.lat) * r / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin((b.lon - a.lon) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x));
}
function toast(msg) {
  const t = document.createElement("div");
  t.className = "toast"; t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2200);
}
async function api(path, body) {
  const res = await fetch(path, body ? { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) } : undefined);
  const data = await res.json().catch(() => ({ error: "bad response" }));
  return { ok: res.ok, status: res.status, data };
}

// ---------- placeholder photos ----------
// Drawn SVG illustrations, seeded per listing: interiors in one-point perspective with
// window light, and exteriors that match the property type. Clearly labelled placeholders.
function rng(seed) {
  let s = (seed * 9301 + 49297) % 233280;
  return () => (s = (s * 9301 + 49297) % 233280) / 233280;
}
const pick = (r, arr) => arr[Math.floor(r() * arr.length)];
function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16), f = c => Math.max(0, Math.min(255, Math.round(c + 255 * amt)));
  return "#" + [f(n >> 16), f((n >> 8) & 255), f(n & 255)].map(v => v.toString(16).padStart(2, "0")).join("");
}
const WALLS = ["#efe7da", "#e9e3d8", "#f2ece4", "#e5e9e3", "#ece3da", "#e3e7ec", "#efe9df"];
const WOODS = ["#c9a27c", "#b98d63", "#d4b48e", "#a97c55", "#cfae86"];
const FABRICS = ["#5d7c74", "#8c6f5a", "#6f7f99", "#a98f6b", "#7d8b6a", "#9a6f6f", "#4f6470"];
const PASTELS = ["#7fb3a9", "#e2a46b", "#8aa4cf", "#d98c8c", "#b9a3d0", "#9cc39b", "#e6c26e"];

function plant(x, y, r, k = 1) {
  const g = pick(r, ["#4f7d5c", "#5f8f63", "#3f6e52"]);
  return `<path d="M${x - 14 * k},${y} L${x + 14 * k},${y} L${x + 10 * k},${y + 26 * k} L${x - 10 * k},${y + 26 * k}Z" fill="#c8b6a0"/>
    <ellipse cx="${x - 10 * k}" cy="${y - 22 * k}" rx="${12 * k}" ry="${24 * k}" fill="${g}" transform="rotate(-25 ${x - 10 * k} ${y - 22 * k})"/>
    <ellipse cx="${x + 10 * k}" cy="${y - 26 * k}" rx="${12 * k}" ry="${26 * k}" fill="${shade(g, .06)}" transform="rotate(22 ${x + 10 * k} ${y - 26 * k})"/>
    <ellipse cx="${x}" cy="${y - 34 * k}" rx="${10 * k}" ry="${26 * k}" fill="${shade(g, -.04)}"/>`;
}

function interior(room, r) {
  const wall = pick(r, WALLS), wood = pick(r, WOODS), fab = pick(r, FABRICS);
  const side = shade(wall, -.07), ceil = shade(wall, .03);
  const ww = room === "Kitchen" || room === "Bathroom" ? 110 : 150 + Math.floor(r() * 40);
  const wx = 320 - ww / 2 + (room === "Living room" || room === "Dining" ? Math.floor(r() * 80) - 40 : 0);
  const planks = Array.from({ length: 11 }, (_, i) => { const xb = i * 64; return `<line x1="${xb}" y1="400" x2="${150 + xb / 640 * 340}" y2="270" stroke="${shade(wood, -.12)}" stroke-width="1.2" opacity=".55"/>`; }).join("");
  let f = "";
  if (room === "Living room") {
    f = `<ellipse cx="320" cy="335" rx="190" ry="34" fill="${shade(wall, -.12)}" opacity=".7"/>
      <rect x="190" y="228" width="260" height="44" rx="14" fill="${shade(fab, .05)}"/>
      <rect x="182" y="262" width="276" height="50" rx="12" fill="${fab}"/>
      <rect x="170" y="246" width="34" height="66" rx="12" fill="${shade(fab, -.05)}"/><rect x="436" y="246" width="34" height="66" rx="12" fill="${shade(fab, -.05)}"/>
      <rect x="232" y="246" width="56" height="28" rx="8" fill="${shade(fab, .18)}"/><rect x="352" y="246" width="56" height="28" rx="8" fill="${shade(fab, .14)}"/>
      <ellipse cx="320" cy="352" rx="78" ry="16" fill="${shade(wood, -.15)}"/><rect x="250" y="340" width="140" height="10" rx="5" fill="${wood}"/>
      ${plant(520, 300, r)}`;
  } else if (room === "Master bedroom" || room === "Bedroom") {
    const w = room === "Bedroom" ? 180 : 230, x = 320 - w / 2;
    f = `<rect x="${x - 6}" y="190" width="${w + 12}" height="74" rx="10" fill="${shade(fab, -.08)}"/>
      <path d="M${x},258 L${x + w},258 L${x + w + 30},338 L${x - 30},338Z" fill="#fbf8f2"/>
      <path d="M${x - 8},290 L${x + w + 8},290 L${x + w + 30},338 L${x - 30},338Z" fill="${fab}"/>
      <rect x="${x + 14}" y="242" width="${w / 2 - 22}" height="26" rx="9" fill="#ffffff"/><rect x="${x + w / 2 + 8}" y="242" width="${w / 2 - 22}" height="26" rx="9" fill="#ffffff"/>
      <rect x="${x - 70}" y="262" width="48" height="44" rx="4" fill="${wood}"/><rect x="${x + w + 22}" y="262" width="48" height="44" rx="4" fill="${wood}"/>
      <path d="M${x - 58},236 L${x - 34},236 L${x - 38},258 L${x - 54},258Z" fill="#f3e2bf"/>`;
  } else if (room === "Kitchen") {
    const cab = pick(r, ["#5f7f74", "#3f5d6b", "#e9e4da", "#7b6a58", "#2f4a43"]);
    f = `<rect x="150" y="76" width="340" height="40" fill="${shade(cab, .04)}"/>${[0, 1, 2, 3].map(i => `<line x1="${150 + i * 85}" y1="76" x2="${150 + i * 85}" y2="116" stroke="${shade(cab, -.1)}"/>`).join("")}
      <rect x="150" y="214" width="340" height="56" fill="${cab}"/><rect x="146" y="208" width="348" height="8" fill="#f4f1ec"/>
      ${[0, 1, 2, 3].map(i => `<line x1="${150 + i * 85}" y1="216" x2="${150 + i * 85}" y2="270" stroke="${shade(cab, -.12)}"/>`).join("")}
      <path d="M220,300 L420,300 L440,346 L200,346Z" fill="${shade(cab, .06)}"/><rect x="196" y="292" width="248" height="10" fill="#f4f1ec"/>
      <circle cx="260" cy="248" r="0"/>`;
  } else if (room === "Bathroom") {
    const tiles = Array.from({ length: 8 }, (_, i) => `<line x1="150" y1="${80 + i * 25}" x2="490" y2="${80 + i * 25}" stroke="${shade(wall, -.1)}" stroke-width=".8"/>`).join("") +
      Array.from({ length: 9 }, (_, i) => `<line x1="${150 + i * 42.5}" y1="60" x2="${150 + i * 42.5}" y2="270" stroke="${shade(wall, -.1)}" stroke-width=".8"/>`).join("");
    f = `${tiles}<rect x="190" y="200" width="130" height="50" rx="4" fill="${wood}"/><rect x="186" y="194" width="138" height="8" fill="#ffffff"/>
      <rect x="205" y="110" width="100" height="70" rx="6" fill="#dfeaf0" stroke="#ffffff" stroke-width="4"/>
      <path d="M360,250 L500,250 Q505,300 470,312 L390,312 Q355,300 360,250Z" fill="#ffffff"/>`;
  } else if (room === "Dining") {
    f = `<line x1="320" y1="0" x2="320" y2="120" stroke="#444" stroke-width="1.5"/><path d="M296,120 L344,120 L334,104 L306,104Z" fill="${pick(r, ["#2f2f2f", "#b9822a", "#e9e4da"])}"/>
      <path d="M210,262 L430,262 L460,300 L180,300Z" fill="${wood}"/><rect x="190" y="300" width="8" height="46" fill="${shade(wood, -.2)}"/><rect x="442" y="300" width="8" height="46" fill="${shade(wood, -.2)}"/>
      ${[230, 300, 370].map(x => `<rect x="${x}" y="226" width="40" height="40" rx="6" fill="${fab}"/>`).join("")}
      ${[150, 450].map(x => `<rect x="${x}" y="276" width="44" height="64" rx="8" fill="${shade(fab, -.06)}"/>`).join("")}`;
  }
  const art = room !== "Kitchen" && room !== "Bathroom" && r() > 0.35
    ? `<rect x="${wx > 300 ? 180 : 400}" y="110" width="58" height="72" fill="${pick(r, PASTELS)}" stroke="#ffffff" stroke-width="5"/>` : "";
  return `<polygon points="0,0 640,0 490,60 150,60" fill="${ceil}"/>
    <polygon points="0,0 150,60 150,270 0,400" fill="${side}"/><polygon points="640,0 490,60 490,270 640,400" fill="${side}"/>
    <rect x="150" y="60" width="340" height="210" fill="${wall}"/>
    <polygon points="0,400 150,270 490,270 640,400" fill="${wood}"/>${planks}
    <rect x="${wx}" y="92" width="${ww}" height="118" fill="url(#sky)"/>
    <g fill="#c6d6e2" opacity=".8">${[0, 1, 2, 3, 4].map(i => `<rect x="${wx + 8 + i * ww / 5}" y="${150 - (i % 3) * 14}" width="${ww / 6}" height="${60 + (i % 3) * 14}"/>`).join("")}</g>
    <rect x="${wx}" y="92" width="${ww}" height="118" fill="none" stroke="#ffffff" stroke-width="6"/><line x1="${wx + ww / 2}" y1="92" x2="${wx + ww / 2}" y2="210" stroke="#ffffff" stroke-width="4"/>
    <polygon points="${wx},210 ${wx + ww},210 ${wx + ww + 70},360 ${wx - 40},360" fill="#fffdf6" opacity=".22"/>
    ${art}${f}`;
}

function exterior(kind, r) {
  const sky = `<rect width="640" height="400" fill="url(#sky)"/>`;
  const trees = x => `<circle cx="${x}" cy="318" r="34" fill="#5f8f63"/><circle cx="${x + 26}" cy="330" r="28" fill="#4f7d5c"/><rect x="${x + 6}" y="340" width="8" height="30" fill="#6b5340"/>`;
  if (kind === "condo") {
    const g1 = pick(r, ["#8fb3c9", "#9fbcc4", "#a7b8d0"]), h1 = 40 + Math.floor(r() * 30), h2 = 90 + Math.floor(r() * 30);
    const tower = (x, w, top, c) => `<rect x="${x}" y="${top}" width="${w}" height="${330 - top}" fill="${c}"/>
      ${Array.from({ length: Math.floor((330 - top) / 16) }, (_, i) => `<rect x="${x - 4}" y="${top + 8 + i * 16}" width="${w + 8}" height="3" fill="#f6f8f9" opacity=".9"/>`).join("")}
      <rect x="${x + w * .62}" y="${top}" width="${w * .38}" height="${330 - top}" fill="#000" opacity=".08"/>`;
    return `${sky}${tower(150, 130, h1, g1)}${tower(340, 120, h2, shade(g1, .05))}
      <rect y="320" width="640" height="80" fill="#cfd8c4"/><rect x="120" y="340" width="400" height="34" rx="6" fill="#6fc3d6"/><rect x="120" y="340" width="400" height="6" fill="#ffffff" opacity=".6"/>
      ${trees(40)}${trees(560)}`;
  }
  if (kind === "landed") {
    const c = pick(r, ["#f3efe6", "#efe6d8", "#e9ece6"]), roof = pick(r, ["#8e5a45", "#5f5a55", "#a8694f"]);
    const house = x => `<rect x="${x}" y="190" width="150" height="140" fill="${c}"/><polygon points="${x - 12},194 ${x + 75},132 ${x + 162},194" fill="${roof}"/>
      <rect x="${x + 18}" y="212" width="46" height="40" fill="#bcd6e6" stroke="#fff" stroke-width="4"/><rect x="${x + 86}" y="212" width="46" height="40" fill="#bcd6e6" stroke="#fff" stroke-width="4"/>
      <rect x="${x + 14}" y="276" width="70" height="54" fill="${shade(c, -.12)}"/><rect x="${x + 100}" y="270" width="34" height="60" fill="#7a5a3e"/>`;
    return `${sky}${house(80)}${house(245)}${house(410)}<rect y="330" width="640" height="70" fill="#c9cfc0"/>
      ${Array.from({ length: 33 }, (_, i) => `<rect x="${i * 20}" y="318" width="3" height="30" fill="#3d3d3d" opacity=".55"/>`).join("")}<rect y="318" width="640" height="3" fill="#3d3d3d" opacity=".55"/>${trees(10)}`;
  }
  // HDB slab block with pastel accent bands, corridor lines and a void deck.
  const accent = pick(r, PASTELS), top = 60 + Math.floor(r() * 30);
  const rows = Math.floor((300 - top) / 20);
  return `${sky}<rect x="70" y="${top}" width="500" height="${330 - top}" fill="#f4efe6"/>
    <rect x="70" y="${top}" width="56" height="${300 - top}" fill="${accent}"/><rect x="514" y="${top}" width="56" height="${300 - top}" fill="${accent}"/>
    ${Array.from({ length: rows }, (_, i) => `<rect x="126" y="${top + 10 + i * 20}" width="388" height="3" fill="${shade(accent, -.15)}" opacity=".7"/>` +
      Array.from({ length: 12 }, (_, j) => `<rect x="${136 + j * 32}" y="${top + 15 + i * 20}" width="18" height="10" fill="#9fb6c4"/>`).join("")).join("")}
    <rect x="70" y="300" width="500" height="30" fill="${shade("#f4efe6", -.18)}"/>${Array.from({ length: 8 }, (_, i) => `<rect x="${90 + i * 64}" y="300" width="10" height="30" fill="#f4efe6"/>`).join("")}
    <rect y="330" width="640" height="70" fill="#a9c08f"/>${trees(20)}${trees(540)}`;
}

function viewScene(r) {
  const hz = 250;
  const layer = (n, base, c, lit) => Array.from({ length: n }, (_, i) => {
    const w = 30 + r() * 40, h = base + r() * 120, x = i * (640 / n) + r() * 10;
    const win = lit ? Array.from({ length: 6 }, () => `<rect x="${x + 4 + r() * (w - 10)}" y="${hz - h + 8 + r() * (h - 20)}" width="3" height="3" fill="#ffd98a" opacity=".85"/>`).join("") : "";
    return `<rect x="${x}" y="${hz - h}" width="${w}" height="${h}" fill="${c}"/>${win}`;
  }).join("");
  return `<rect width="640" height="400" fill="url(#dusk)"/>${layer(14, 40, "#7d84a6", false)}${layer(11, 70, "#4b5276", true)}
    <rect y="${hz}" width="640" height="${400 - hz}" fill="#39406a"/><rect y="${hz}" width="640" height="2" fill="#f6c08a" opacity=".6"/>
    <rect x="0" y="330" width="640" height="70" fill="#2b3150"/><rect x="40" y="300" width="560" height="10" fill="#d9d4cc"/>${[60, 160, 260, 360, 460, 560].map(x => `<rect x="${x}" y="300" width="6" height="40" fill="#d9d4cc"/>`).join("")}`;
}

const photoCache = new Map();
function photo(room, seed, kind = "hdb") {
  const key = `${room}|${seed}|${kind}`;
  if (photoCache.has(key)) return photoCache.get(key);
  const r = rng(seed + 1);
  const body = room === "Exterior" ? exterior(kind, r) : room === "View" ? viewScene(r) : interior(room, r);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400">
    <defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a9cbe6"/><stop offset="1" stop-color="#eef5f9"/></linearGradient>
    <linearGradient id="dusk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5a6aa3"/><stop offset=".6" stop-color="#e9a88a"/><stop offset="1" stop-color="#f6c08a"/></linearGradient></defs>
    ${body}
    <rect x="14" y="14" width="${room.length * 7 + 92}" height="24" rx="12" fill="rgba(20,32,27,.55)"/>
    <text x="26" y="30" font-family="Inter,system-ui,sans-serif" font-size="12" fill="#fff">Placeholder · ${room}</text>
  </svg>`;
  const uri = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
  photoCache.set(key, uri);
  return uri;
}
const cover = l => photo(l.images[0].room, l.images[0].seed, l.kind);

// ---------- value vs estimate ----------
const gap = l => l.mode === "sale" ? l.price / l.valuation.est - 1 : null;
function vbadge(l) {
  const g = gap(l);
  if (g == null) return "";
  const p = Math.abs(g * 100).toFixed(1);
  if (Math.abs(g) < 0.02) return `<span class="vbadge fair">≈ at estimate</span>`;
  return g < 0 ? `<span class="vbadge below">▼ ${p}% below estimate</span>` : `<span class="vbadge above">▲ ${p}% above estimate</span>`;
}

// ---------- shortlist & compare ----------
function setShort(id, on) {
  on ? shortlist.add(id) : shortlist.delete(id);
  store.set("shortlist", [...shortlist]);
  updateCounts();
}
function setCompare(id, on) {
  compare = compare.filter(x => x !== id);
  if (on) {
    if (compare.length >= 4) { toast("You can compare up to 4 homes"); renderDock(); return false; }
    compare.push(id);
  }
  store.set("compare", compare);
  updateCounts(); renderDock();
  return true;
}
function updateCounts() {
  $("#nShort").textContent = shortlist.size;
  $("#nCompare").textContent = compare.length;
}
function renderDock() {
  const dock = $("#dock");
  if (!compare.length || location.hash.startsWith("#/compare")) { dock.innerHTML = ""; return; }
  dock.innerHTML = `<div class="compare-dock"><div class="wrap">
    <span>${compare.length} home${compare.length > 1 ? "s" : ""} selected to compare: ${compare.map(id => esc(S.byId[id]?.name || id)).join(" · ")}</span>
    <span class="row"><button class="btn small" id="dockClear">Clear</button><a class="btn small primary" href="#/compare">Compare</a></span>
  </div></div>`;
  $("#dockClear").onclick = () => { compare = []; store.set("compare", compare); updateCounts(); renderDock(); $$("[data-compare]").forEach(c => (c.checked = false)); };
}
// Event delegation for hearts and compare checkboxes anywhere on the page.
document.addEventListener("click", e => {
  const h = e.target.closest("[data-heart]");
  if (h) {
    e.preventDefault();
    const on = !shortlist.has(h.dataset.heart);
    setShort(h.dataset.heart, on);
    $$(`[data-heart="${h.dataset.heart}"]`).forEach(x => { x.setAttribute("aria-pressed", on); x.textContent = on ? "♥" : "♡"; });
    toast(on ? "Saved to shortlist" : "Removed from shortlist");
  }
});
document.addEventListener("change", e => {
  const c = e.target.closest("[data-compare]");
  if (c && !setCompare(c.dataset.compare, c.checked)) c.checked = false;
});

// ---------- listing card ----------
function card(l) {
  const specs = [
    l.beds ? `${l.beds} bed` : "", l.baths ? `${l.baths} bath` : "",
    `${l.sqft.toLocaleString("en-SG")} sqft${l.kind === "landed" ? " land" : ""}`, psfText(l),
  ].filter(Boolean).map(s => `<span>${s}</span>`).join("");
  const on = shortlist.has(l.id);
  return `<article class="card" data-id="${l.id}">
    <a class="cover" href="#/listing/${l.id}"><img loading="lazy" src="${cover(l)}" alt="Placeholder photo of ${esc(l.name)}"></a>
    <span class="tag">${KIND_NAME[l.kind]}${l.mode === "rent" ? " · For rent" : ""}${l.user ? " · By owner" : ""}</span>
    <button class="heart" data-heart="${l.id}" aria-pressed="${on}" aria-label="Save to shortlist">${on ? "♥" : "♡"}</button>
    <div class="body">
      <div class="price num">${priceText(l)}</div>
      <div>${vbadge(l)}</div>
      <a class="name" href="#/listing/${l.id}">${esc(l.name)}</a>
      <div class="faint">${esc(l.property_type)} · ${esc(l.town || ("D" + l.district + " · " + title(l.street)))}</div>
      <div class="specs num">${specs}</div>
      <div class="foot"><span>Listed ${ago(l.listed)}</span>
        <label class="compare-toggle"><input type="checkbox" data-compare="${l.id}" ${compare.includes(l.id) ? "checked" : ""}> Compare</label></div>
    </div>
  </article>`;
}

// ---------- maps ----------
let maps = [];
function newMap(container, opts) {
  const m = new maplibregl.Map({ container, style: MAP_STYLE, attributionControl: { compact: true }, ...opts });
  m.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");
  maps.push(m);
  return m;
}
function miniMap(el, lat, lon, label) {
  const m = newMap(el, { center: [lon, lat], zoom: 15.5, scrollZoom: false });
  new maplibregl.Marker({ color: "#12614c" }).setLngLat([lon, lat]).setPopup(new maplibregl.Popup().setText(label)).addTo(m);
  return m;
}

// ---------- router ----------
const routes = [
  [/^\/$/, home], [/^\/search$/, searchPage], [/^\/listing\/(\w+)$/, listingPage],
  [/^\/projects$/, projectsPage], [/^\/project\/(.+)$/, projectPage], [/^\/trends$/, trendsPage],
  [/^\/tools$/, toolsPage], [/^\/shortlist$/, shortlistPage], [/^\/compare$/, comparePage],
  [/^\/agent\/(\w+)$/, agentPage], [/^\/sell$/, sellPage], [/^\/enquiries$/, enquiriesPage],
  [/^\/map$/, valueMapPage], [/^\/value$/, valuePage], [/^\/about$/, aboutPage],
];
let lastPath = null;
let cleanups = [];
const currentPath = () => (location.hash.slice(1) || "/").split("?")[0].split("#")[0];
function route() {
  const [rawPath, query = ""] = (location.hash.slice(1) || "/").split("?");
  const path = rawPath.split("#")[0];  // "#/tools#mortgage" -> "/tools" (anchor handled by the page)
  const q = qsParse(query);
  cleanups.forEach(fn => fn());
  cleanups = [];
  maps.forEach(m => m.remove());
  maps = [];
  document.body.dataset.route = path;  // not "page": [data-page] is the pager's hook
  $$("#nav a").forEach(a => a.classList.toggle("active",
    (a.dataset.nav === "sale" && path === "/search" && q.mode !== "rent") || (a.dataset.nav === "rent" && path === "/search" && q.mode === "rent") ||
    (a.dataset.nav === "projects" && path.startsWith("/project")) || ("/" + a.dataset.nav === path)));
  const main = $("#main");
  for (const [re, fn] of routes) {
    const m = path.match(re);
    if (m) {
      fn(main, q, ...m.slice(1).map(decodeURIComponent));
      if (path !== lastPath) window.scrollTo(0, 0);
      lastPath = path;
      renderDock();
      return;
    }
  }
  main.innerHTML = `<div class="wrap"><div class="empty" style="margin:40px 0">Page not found. <a href="#/">Go home</a></div></div>`;
}
window.addEventListener("hashchange", route);

// ---------- shared colour helpers ----------
const rgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
function quantileBreaks(values, n) {
  const v = values.filter(x => x != null).sort((a, b) => a - b);
  return Array.from({ length: n - 1 }, (_, i) => v[Math.floor(v.length * (i + 1) / n)]);
}
const binOf = (v, breaks) => { let i = 0; while (i < breaks.length && v >= breaks[i]) i++; return i; };

// ---------- home ----------
const HERO_RAMP = ["#1d5444", "#246b55", "#2e8466", "#40a07b", "#64bc93", "#9ad6b6", "#dbf5e7"];
const DARK_STYLE = "https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json";

function heroCity(el) {
  const pts = S.hero;
  const br = quantileBreaks(pts.map(p => p[3]), HERO_RAMP.length);
  const cols = HERO_RAMP.map(rgb);
  const color = p => cols[binOf(p[3], br)];
  const m = new maplibregl.Map({ container: el, style: DARK_STYLE, center: [103.74, 1.335], zoom: 11.15, pitch: 58, bearing: -16,
    interactive: false, attributionControl: { compact: true } });
  const layer = (id, data, radius) => new deck.ColumnLayer({
    id, data, getPosition: p => [p[0], p[1]], radius, diskResolution: 6, extruded: true, elevationScale: 2.4,
    getElevation: p => p[2], getFillColor: color, material: { ambient: 0.55, diffuse: 0.65, shininess: 24 },
  });
  m.addControl(new deck.MapboxOverlay({ interleaved: false, layers: [layer("tall", pts.filter(p => p[4] !== 2), 42), layer("landed", pts.filter(p => p[4] === 2), 24)] }));
  let raf = 0;
  const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const spin = () => { m.setBearing(m.getBearing() + 0.025); raf = requestAnimationFrame(spin); };
  m.on("load", () => { if (!still) spin(); });
  cleanups.push(() => { cancelAnimationFrame(raf); m.remove(); });
  return br;
}

