// ---------- sg-homes data (value map, valuations) ----------
const VM = {
  hdb:    { name: "HDB",    ramp: ["#b7d3f6", "#86b6ef", "#5598e7", "#2a78d6", "#1c5cab", "#104281", "#0d366b"] },
  condo:  { name: "Condo",  ramp: ["#fbd3bf", "#f6ad8b", "#f08a5d", "#eb6834", "#c9501f", "#a03d15", "#77300f"] },
  landed: { name: "Landed", ramp: ["#bfeedd", "#8fdcbf", "#5cc89f", "#1baf7a", "#138e62", "#0d6e4c", "#08513a"] },
};
async function loadSG() {
  if (S.sg) return S.sg;
  const [b, c, l] = await Promise.all(["blocks", "condo", "landed"].map(n => fetch(`/sg/${n}.json`).then(r => r.json())));
  S.sg = { hdb: b.blocks, condo: c.projects, landed: l.projects, meta: b.meta };
  S.sgById = Object.fromEntries(Object.entries({ hdb: b.blocks, condo: c.projects, landed: l.projects })
    .map(([k, arr]) => [k, Object.fromEntries(arr.map(x => [x.id, x]))]));
  if (!S.forecast && b.meta.forecast) S.forecast = b.meta.forecast;
  return S.sg;
}
const placeName = (kind, x) => kind === "hdb" ? `Blk ${x.block} ${title(x.street)}`
  : x.project === "LANDED HOUSING DEVELOPMENT" ? `Landed homes, ${title(x.street)}` : title(x.project);
const placeSub = (kind, x) => kind === "hdb" ? `HDB · ${title(x.town)}` : `${VM[kind].name} · ${title(x.street)} · D${x.district} (${x.segment})`;
const listedAt = (kind, id) => S.listings.filter(l => l.ref.kind === kind && l.ref.id === id);

// Shared unit valuation form: place = sg-homes record. onResult(value, params) is called on success.
function valueForm(el, kind, x, onResult, showResult = true) {
  const top = [...x.units].sort((a, b) => b.n - a.n)[0];
  const typeField = kind === "condo" ? "" : `<label class="field">${kind === "hdb" ? "Flat type" : "House type"}<select name="type">${x.units.map(u => `<option value="${esc(u.type)}" ${u === top ? "selected" : ""}>${esc(title(u.type))}</option>`).join("")}</select></label>`;
  const floorField = kind === "landed" ? "" : `<label class="field">${kind === "hdb" ? "Storey" : "Floor"}<input type="number" name="floor" min="1" max="${(x.floors || 40) + (kind === "condo" ? 5 : 0)}" value="${top.floor ?? Math.max(1, Math.round((x.floors || 12) / 2))}"></label>`;
  el.innerHTML = `<form class="unit-form">${typeField}${floorField}
      <label class="field">${kind === "landed" ? "Land area (sqft)" : "Size (sqft)"}<input type="number" name="sqft" min="200" value="${Math.round(top.sqm * SQFT)}"></label>
      <button class="btn primary" type="submit">Get estimate</button></form><div class="unit-result"></div>`;
  const form = $("form", el), out = $(".unit-result", el);
  if (form.type) form.type.onchange = () => { const u = x.units.find(u => u.type === form.type.value); form.sqft.value = Math.round(u.sqm * SQFT); };
  form.onsubmit = async e => {
    e.preventDefault();
    const params = { kind, id: x.id, sqm: (+form.sqft.value / SQFT).toFixed(1) };
    if (kind === "hdb") Object.assign(params, { type: form.type.value, storey: form.floor.value });
    if (kind === "condo") params.floor = form.floor.value;
    if (kind === "landed") params.type = form.type.value;
    out.innerHTML = `<p class="faint">Valuing…</p>`;
    const r = await api("/api/value", params);
    if (!r.ok) { out.innerHTML = `<div class="err">${esc(r.data.error || "Valuation server unavailable")}</div>`; return; }
    const v = r.data;
    if (!showResult) { out.innerHTML = ""; onResult && onResult(v, { ...params, sqft: form.sqft.value, floor: form.floor?.value, type: form.type?.value }); return; }
    out.innerHTML = `<div class="panel dark" style="margin-top:4px"><div class="faint">Estimated value</div><div class="est-big num">${fmt$(v.est)}</div>
      <div class="faint">80% range ${fmtK(v.lo)} – ${fmtK(v.hi)} · $${Math.round(v.psm / SQFT).toLocaleString("en-SG")} psf</div>
      ${v.warnings.map(w => `<div class="err" style="margin-top:8px">${esc(w)}</div>`).join("")}</div>`;
    onResult && onResult(v, { ...params, sqft: form.sqft.value, floor: form.floor?.value, type: form.type?.value });
  };
  return form;
}

// HDB projection: today's estimate x lease-decay curve x market scenario, as a chart + table.
let scenarioIx = 2;
async function projectionBlock(el, leaseStart, est, label) {
  if (!S.forecast) { const r = await api("/api/forecast"); if (!r.ok) { el.innerHTML = `<p class="faint">Lease outlook unavailable.</p>`; return; } S.forecast = r.data; }
  const F = S.forecast, D = F.decay, S0 = F.scenarios;
  const [vy, vm] = S.meta.valuation_month.split("-").map(Number);
  const age0 = vy + (vm - 1) / 12 - leaseStart, y0 = vy;
  const rel = (arr, a) => { const x = Math.min(Math.max(a, 0), arr.length - 1), i = Math.floor(x), f = x - i; return i + 1 < arr.length ? arr[i] * (1 - f) + arr[i + 1] * f : arr[i]; };
  const proj = (rate, years) => {
    const out = [];
    for (let k = 0; k <= years && age0 + k <= 99; k++) {
      const ratio = arr => rel(arr, age0 + k) / rel(arr, age0), m = (1 + rate) ** k, band = [ratio(D.r_lo), ratio(D.r_hi)];
      out.push({ k, v: est * ratio(D.r) * m, lo: est * Math.min(...band) * m, hi: est * Math.max(...band) * m, ex: age0 + k > D.max_observed_age });
    }
    return out;
  };
  const draw = () => {
    const pts = proj(S0[scenarioIx].rate, 20), d10 = proj(0, 10)[10];
    const W = 600, H = 190, L = 52, R = 12, T = 10, B = 24;
    const ys = pts.flatMap(p => [p.lo, p.hi]), pad = (Math.max(...ys) - Math.min(...ys)) * 0.08 || est * 0.05;
    const lo = Math.max(0, Math.min(...ys) - pad), hi = Math.max(...ys) + pad, last = pts[pts.length - 1].k || 1;
    const sx = k => L + k / last * (W - L - R), sy = v => H - B - (v - lo) / (hi - lo) * (H - T - B);
    const path = a => a.map((p, i) => `${i ? "L" : "M"}${sx(p.k).toFixed(1)},${sy(p.v).toFixed(1)}`).join("");
    const seen = pts.filter(p => !p.ex), beyond = pts.filter((p, i) => p.ex || (pts[i + 1] && pts[i + 1].ex));
    const band = `M${pts.map(p => `${sx(p.k)},${sy(p.hi)}`).join("L")}L${[...pts].reverse().map(p => `${sx(p.k)},${sy(p.lo)}`).join("L")}Z`;
    const ticks = [0.15, 0.5, 0.85].map(f => lo + (hi - lo) * f);
    el.innerHTML = `<p>${d10 ? `Lease decay alone: <b>${((d10.v / est - 1) * 100).toFixed(1)}%</b> relative to the HDB market over 10 years (${Math.max(0, Math.round(99 - age0 - 10))} years left in ${y0 + 10}).` : "The lease runs out within 10 years."}</p>
      <div class="chips" style="margin:8px 0">${S0.map((s, i) => `<button class="chip-btn" data-sc="${i}" aria-pressed="${i === scenarioIx}">${esc(s.name)} ${s.rate >= 0 ? "+" : ""}${(s.rate * 100).toFixed(1)}%/yr</button>`).join("")}</div>
      <div class="chart proj"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Projected value under the ${esc(S0[scenarioIx].name)} scenario">
        ${ticks.map(t => `<line class="grid" x1="${L}" x2="${W - R}" y1="${sy(t)}" y2="${sy(t)}"/><text class="axis" x="${L - 8}" y="${sy(t) + 4}" text-anchor="end">${fmtK(t)}</text>`).join("")}
        ${[0, 5, 10, 15, 20].filter(k => k <= last).map(k => `<text class="axis" x="${sx(k)}" y="${H - 6}" text-anchor="${k === last ? "end" : k === 0 ? "start" : "middle"}">${y0 + k}</text>`).join("")}
        <path d="${band}" fill="#9ad6b6" opacity=".35"/>
        <path d="${path(seen)}" fill="none" stroke="#0f5c47" stroke-width="2.5" stroke-linejoin="round"/>
        ${beyond.length > 1 ? `<path d="${path(beyond)}" fill="none" stroke="#0f5c47" stroke-width="2.5" stroke-dasharray="5 4"/>` : ""}
        ${pts.map(p => `<circle cx="${sx(p.k)}" cy="${sy(p.v)}" r="8" fill="transparent"><title>${y0 + p.k}: ${fmt$(p.v)}</title></circle>`).join("")}
      </svg></div>
      <table class="t"><tr><th>Scenario</th>${[5, 10, 20].map(h => `<th class="r">${y0 + h}</th>`).join("")}</tr>
        ${S0.map(s => `<tr><td>${esc(s.name)}</td>${[5, 10, 20].map(h => { const p = proj(s.rate, h)[h]; return `<td class="r">${p ? fmtK(p.v) : "–"}</td>`; }).join("")}</tr>`).join("")}</table>
      <p class="faint">${esc(label || "Typical unit")}. Shaded band = uncertainty in the lease-decay curve; the market path is a scenario, not a prediction.
        ${beyond.length > 1 ? "Dashed = older than any flat sold so far; value assumed to fall in a straight line to $0 at 99 years." : ""}</p>`;
    $$("[data-sc]", el).forEach(b => b.onclick = () => { scenarioIx = +b.dataset.sc; draw(); });
  };
  draw();
}

