// ---------- calculators ----------
const BSD = [[180e3, 0.01], [180e3, 0.02], [640e3, 0.03], [500e3, 0.04], [1.5e6, 0.05], [Infinity, 0.06]];
const ABSD = { SC: [0, 0.2, 0.3], PR: [0.05, 0.3, 0.35], FR: [0.6, 0.6, 0.6], EN: [0.65, 0.65, 0.65] };
function bsd(price) {
  let left = price, duty = 0;
  for (const [band, rate] of BSD) { const x = Math.min(left, band); duty += x * rate; left -= x; if (left <= 0) break; }
  return duty;
}
const monthly = (loan, ratePct, years) => { const r = ratePct / 100 / 12, n = years * 12; return r === 0 ? loan / n : loan * r / (1 - (1 + r) ** -n); };
const pv = (pmt, ratePct, years) => { const r = ratePct / 100 / 12, n = years * 12; return r === 0 ? pmt * n : pmt * (1 - (1 + r) ** -n) / r; };

function mortgageWidget(el, price = 1e6, kind = "condo") {
  el.innerHTML = `<div class="grid2">
    <label class="field">Property price<input type="number" name="price" value="${Math.round(price)}" step="1000"></label>
    <label class="field">Loan-to-value (%)<select name="ltv"><option value="75" selected>75% (first housing loan)</option><option value="55">55% (long tenure / older borrower)</option><option value="45">45% (second housing loan)</option></select></label>
    <label class="field">Interest rate (% a year)<input type="number" name="rate" value="${kind === "hdb" ? 2.6 : 3.0}" step="0.05"></label>
    <label class="field">Loan tenure (years)<input type="number" name="years" value="25" min="5" max="35"></label>
  </div><div id="mOut" style="margin-top:12px"></div>`;
  const calc = () => {
    const f = Object.fromEntries($$("input,select", el).map(i => [i.name, +i.value]));
    const loan = f.price * f.ltv / 100, pay = monthly(loan, f.rate, f.years), interest = pay * f.years * 12 - loan;
    const stress = kind === "hdb" ? 3.0 : 4.0, limit = kind === "hdb" ? 0.30 : 0.55;
    const income = monthly(loan, Math.max(stress, f.rate), f.years) / limit;
    $("#mOut", el).innerHTML = `<div class="stats">
      <div class="stat"><div class="faint">Monthly repayment</div><div class="v num">${fmt$(pay)}</div></div>
      <div class="stat"><div class="faint">Loan amount</div><div class="v num">${fmtK(loan)}</div><div class="faint">Down payment ${fmtK(f.price - loan)} (at least 5% cash)</div></div>
      <div class="stat"><div class="faint">Total interest</div><div class="v num">${fmtK(interest)}</div></div></div>
      <p class="faint">Income needed to pass ${kind === "hdb" ? "MSR (30% of income, HDB/EC)" : "TDSR (55% of income)"} at the ${stress}% medium-term rate, with no other debts: about <b>${fmt$(income)}</b>/month.</p>`;
  };
  el.oninput = calc;
  calc();
}

function stampWidget(el, price = 1e6) {
  el.innerHTML = `<div class="grid3">
    <label class="field">Purchase price<input type="number" name="price" value="${Math.round(price)}" step="1000"></label>
    <label class="field">Buyer<select name="who"><option value="SC">Singapore Citizen</option><option value="PR">Permanent Resident</option><option value="FR">Foreigner</option><option value="EN">Entity</option></select></label>
    <label class="field">This will be my<select name="n"><option value="0">1st property</option><option value="1">2nd property</option><option value="2">3rd or later</option></select></label>
  </div><div id="sOut" style="margin-top:12px"></div>`;
  const calc = () => {
    const p = +$("[name=price]", el).value, who = $("[name=who]", el).value, n = +$("[name=n]", el).value;
    const b = bsd(p), a = p * ABSD[who][n];
    $("#sOut", el).innerHTML = `<table class="t"><tr><td>Buyer's stamp duty (BSD)</td><td class="r">${fmt$(b)}</td></tr>
      <tr><td>Additional buyer's stamp duty (ABSD, ${(ABSD[who][n] * 100).toFixed(0)}%)</td><td class="r">${fmt$(a)}</td></tr>
      <tr><td><b>Total stamp duty</b></td><td class="r"><b>${fmt$(a + b)}</b></td></tr></table>
      <p class="faint">Residential rates from Feb/Apr 2023. Couples and ABSD remission cases differ; check IRAS.</p>`;
  };
  el.oninput = calc;
  calc();
}

function affordWidget(el) {
  el.innerHTML = `<div class="grid3">
    <label class="field">Gross monthly income (household)<input type="number" name="income" value="10000" step="500"></label>
    <label class="field">Other monthly debt repayments<input type="number" name="debt" value="0" step="100"></label>
    <label class="field">Property<select name="type"><option value="hdb">HDB flat (MSR applies)</option><option value="private">Private / resale EC</option></select></label>
    <label class="field">Loan tenure (years)<input type="number" name="years" value="25" min="5" max="35"></label>
    <label class="field">Cash + CPF for down payment<input type="number" name="cash" value="200000" step="5000"></label>
  </div><div id="aOut" style="margin-top:12px"></div>`;
  const calc = () => {
    const f = Object.fromEntries($$("input,select", el).map(i => [i.name, i.type === "number" ? +i.value : i.value]));
    const hdb = f.type === "hdb", stress = hdb ? 3.0 : 4.0;
    const tdsr = 0.55 * f.income - f.debt, msr = hdb ? 0.30 * f.income : Infinity;
    const pay = Math.max(0, Math.min(tdsr, msr));
    const loan = pv(pay, stress, f.years);
    const byLoan = loan / 0.75, byCash = f.cash / 0.25, maxPrice = Math.min(byLoan, byCash);
    const kind = hdb ? "hdb" : "condo";
    $("#aOut", el).innerHTML = `<div class="stats">
      <div class="stat"><div class="faint">Max monthly repayment</div><div class="v num">${fmt$(pay)}</div><div class="faint">${hdb && msr < tdsr ? "Limited by MSR (30%)" : "Limited by TDSR (55%)"}</div></div>
      <div class="stat"><div class="faint">Max loan (at ${stress}% stress rate)</div><div class="v num">${fmtK(loan)}</div></div>
      <div class="stat"><div class="faint">Max price you can afford</div><div class="v num">${fmtK(maxPrice)}</div><div class="faint">${byCash < byLoan ? "Limited by your 25% down payment" : "Limited by the loan"}</div></div></div>
      <p><a class="btn primary small" href="#/search?mode=sale&kind=${kind}&max=${Math.round(maxPrice)}&sort=discount">See ${KIND_NAME[kind]} homes under ${fmtK(maxPrice)}</a></p>
      <p class="faint">Assumes 75% LTV and no other property loans. Banks use their own assessment; this is a rough guide.</p>`;
  };
  el.oninput = calc;
  calc();
}

