  if (!r.ok) { $("#pEst").innerHTML = `<h2>Estimated values</h2><p class="faint">Unavailable (is app.py running?).</p>`; return; }
  const ref = r.data;
  $("#pEst").innerHTML = `<h2>Estimated values</h2><table class="t"><tr><th>Typical unit</th><th class="r">Size</th><th class="r">Floor</th><th class="r">Estimate</th><th class="r">80% range</th></tr>
    ${ref.units.map(u => `<tr><td>${bandLabel(u.type)}</td><td class="r">${Math.round(u.sqm * SQFT).toLocaleString("en-SG")} sqft</td><td class="r">${u.floor ?? "–"}</td>
    <td class="r"><b>${fmt$(u.est)}</b></td><td class="r">${fmtK(u.lo)} – ${fmtK(u.hi)}</td></tr>`).join("")}</table>
    <p class="faint">Valued as a resale at each size band's median floor (sg-homes condo model, median backtest error ${(S.meta.eval.condo * 100).toFixed(1)}%).</p>`;
  dotChart($("#pChart"), ref.tx.map(t => ({ d: t[0], v: t[4] / t[3] / SQFT, kind: t[1] })));
  $("#pTx").innerHTML = `<h2>Transactions</h2><table class="t"><tr><th>Month</th><th>Sale</th><th>Floor</th><th class="r">Size</th><th class="r">Price</th><th class="r">$ psf</th></tr>
    ${ref.tx.map(t => `<tr><td>${t[0]}</td><td>${esc(t[1])}</td><td>${esc(t[2])}</td><td class="r">${Math.round(t[3] * SQFT).toLocaleString("en-SG")} sqft</td>
    <td class="r">${fmt$(t[4])}</td><td class="r">$${Math.round(t[4] / t[3] / SQFT).toLocaleString("en-SG")}</td></tr>`).join("")}</table>
    <p class="faint">Most recent ${ref.tx.length} URA transactions.</p>`;
