function bandLabel(type) {
  const m = type.match(/^(Under )?(\d+)(?:–(\d+))?(\+)? sqm$/);
  if (!m) return esc(title(type));
  const f = v => Math.round(v * SQFT).toLocaleString("en-SG");
  return m[1] ? `Under ${f(+m[2])} sqft` : m[4] ? `${f(+m[2])}+ sqft` : `${f(+m[2])}–${f(+m[3])} sqft`;
}

// Scatter of $psf over time, coloured by sale type (new sale / resale / sub sale).
function dotChart(el, pts) {
  if (!pts.length) { el.innerHTML = `<p class="faint">No transactions.</p>`; return; }
  const W = 640, H = 220, L = 54, R = 16, T = 12, B = 26;
  const t = s => new Date(s + "-01").getTime();
  const x0 = Math.min(...pts.map(p => t(p.d))), x1 = Math.max(Date.now(), ...pts.map(p => t(p.d)));
  const ys = pts.map(p => p.v), pad = (Math.max(...ys) - Math.min(...ys)) * 0.1 || 50;
  const y0 = Math.min(...ys) - pad, y1 = Math.max(...ys) + pad;
  const sx = v => L + (v - x0) / (x1 - x0 || 1) * (W - L - R), sy = v => H - B - (v - y0) / (y1 - y0) * (H - T - B);
  const colors = { "New Sale": "#eb6834", "Resale": "#2a78d6", "Sub Sale": "#1baf7a" };
  const kinds = [...new Set(pts.map(p => p.kind))];
  const yearsTicks = [];
  for (let y = new Date(x0).getFullYear() + 1; y <= new Date(x1).getFullYear(); y++) yearsTicks.push(y);
  const ticks = [0.15, 0.5, 0.85].map(f => y0 + (y1 - y0) * f);
  el.innerHTML = `<div class="legend">${kinds.map(k => `<span><i style="background:${colors[k] || "#888"};height:8px;width:8px;border-radius:50%"></i>${esc(k)}</span>`).join("")}</div>
    <div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Transaction prices per square foot over time">
    ${ticks.map(v => `<line class="grid" x1="${L}" x2="${W - R}" y1="${sy(v)}" y2="${sy(v)}"/><text class="axis" x="${L - 8}" y="${sy(v) + 4}" text-anchor="end">${psfFmt(v)}</text>`).join("")}
    ${yearsTicks.map(y => `<text class="axis" x="${sx(new Date(y, 0, 1).getTime())}" y="${H - 6}" text-anchor="middle">${y}</text>`).join("")}
    ${pts.map(p => `<circle cx="${sx(t(p.d)).toFixed(1)}" cy="${sy(p.v).toFixed(1)}" r="4.5" fill="${colors[p.kind] || "#888"}" stroke="var(--surface)" stroke-width="1.5"><title>${p.d} · ${p.kind} · ${psfFmt(p.v)} psf</title></circle>`).join("")}
    </svg></div>`;
}

