function comparePage(main) {
  const items = compare.map(id => S.byId[id]).filter(Boolean);
  if (!items.length) { main.innerHTML = `<div class="wrap" style="padding:24px 16px"><h1>Compare homes</h1><div class="empty" style="margin-top:14px">Tick “Compare” on up to 4 listings to see them side by side.</div></div>`; return; }
  const best = (f, dir) => { const vals = items.map(f).filter(v => v != null); const b = dir < 0 ? Math.min(...vals) : Math.max(...vals); return v => vals.length > 1 && v === b; };
  const rows = [
    ["Price", l => l.price, l => priceText(l), -1], ["Our estimate", l => l.valuation.est, l => fmt$(l.valuation.est)],
    ["vs estimate", l => gap(l), l => l.mode === "sale" ? vbadge(l) : "Rental", -1], ["$ psf", l => l.psf, psfText, -1],
    ["Size", l => l.sqft, l => `${l.sqft.toLocaleString("en-SG")} sqft`, 1], ["Bedrooms", l => l.beds, l => l.beds, 1], ["Bathrooms", l => l.baths, l => l.baths, 1],
    ["Type", null, l => esc(l.property_type)], ["Tenure", null, l => esc(l.tenure)],
    ["Lease left", l => l.remaining_lease, l => l.remaining_lease != null ? `${l.remaining_lease} yrs` : l.tenure === "Freehold" ? "Freehold" : "–", 1],
    ["Floor", null, l => l.floor_label || "–"], ["Nearest MRT", l => l.mrt_m, l => `${esc(l.mrt)} · ${l.mrt_m} m`, -1],
    ["Schools ≤1 km", l => l.schools_1km, l => l.schools_1km, 1], ["Listed", null, l => ago(l.listed)],
  ];
  main.innerHTML = `<div class="wrap" style="padding:24px 16px"><h1>Compare homes</h1>
    <p class="muted">Bold = best in row.</p>
    <div class="compare-table"><table class="t"><tr><th></th>${items.map(l => `<th style="width:${90 / items.length}%"><a href="#/listing/${l.id}"><img src="${cover(l)}" alt="" style="border-radius:8px;aspect-ratio:16/10;object-fit:cover;width:100%"></a>
      <a href="#/listing/${l.id}" style="font-size:14px;color:var(--text);font-weight:600">${esc(l.name)}</a><br><button class="btn small" data-rm="${l.id}" style="margin-top:4px">Remove</button></th>`).join("")}</tr>
      ${rows.map(([name, val, show, dir]) => { const isBest = val && dir ? best(val, dir) : () => false;
        return `<tr><td class="muted">${name}</td>${items.map(l => `<td class="${isBest(val ? val(l) : null) ? "best" : ""}">${show(l)}</td>`).join("")}</tr>`; }).join("")}
    </table></div></div>`;
  $$("[data-rm]").forEach(b => b.onclick = () => { setCompare(b.dataset.rm, false); route(); });
}

