// ---------- sell ----------
function sellPage(main, q = {}) {
  const st = { kind: "hdb", place: null };
  main.innerHTML = `<div class="wrap" style="padding:24px 16px;max-width:880px">
    <h1>List your home</h1><p class="muted">Pick your block or project and we'll suggest a price from recent sales, before you publish.</p>
    <form id="sell" class="panel" style="display:flex;flex-direction:column;gap:14px;margin-top:16px">
      <div class="row" style="flex-wrap:wrap;gap:12px">
        <div class="seg" id="sKind">${["hdb", "condo", "landed"].map(k => `<button type="button" data-k="${k}" aria-pressed="${k === "hdb"}">${KIND_NAME[k]}</button>`).join("")}</div>
        <div class="seg" id="sMode"><button type="button" data-m="sale" aria-pressed="true">Sell</button><button type="button" data-m="rent" aria-pressed="false">Rent out</button></div>
      </div>
      <label class="field">Block or project<input type="search" id="placeQ" placeholder="e.g. 406 Ang Mo Kio, or a condo name" autocomplete="off"></label>
      <div id="placeRes" class="chips"></div>
      <div id="placeSel" class="faint">No block or project selected.</div>
      <div class="grid3">
        <label class="field" id="typeF">Flat / house type<select name="type"></select></label>
        <label class="field" id="floorF">Storey / floor<input type="number" name="floor" min="1" value="5"></label>
        <label class="field">Size (sqft)<input type="number" name="sqft" min="200" required></label>
        <label class="field">Bedrooms<input type="number" name="beds" min="1" max="10" value="3" required></label>
        <label class="field">Bathrooms<input type="number" name="baths" min="1" max="10" value="2" required></label>
        <label class="field">Furnishing<select name="furnishing"><option>Unfurnished</option><option>Partially furnished</option><option>Fully furnished</option></select></label>
      </div>
      <div id="suggest" class="panel" style="background:var(--surface-2)"><span class="faint">Choose a block or project and size to get a price suggestion.</span></div>
      <label class="field"><span id="priceLabel">Asking price ($)</span><input type="number" name="price" min="1" required></label>
      <label class="field">Description<textarea name="description" placeholder="What makes your home special?"></textarea></label>
      <div class="grid2"><label class="field">Your name<input type="text" name="name" required></label><label class="field">Email<input type="email" name="email" required></label></div>
      <div class="row"><button class="btn primary" type="submit">Publish listing</button><span id="sellMsg"></span></div>
    </form></div>`;
  const form = $("#sell");
  let mode = "sale", timer;
  const syncFields = () => {
    $("#floorF").hidden = st.kind === "landed";
    $("#typeF").hidden = st.kind === "condo";
    $("#priceLabel").textContent = mode === "rent" ? "Asking rent ($ per month)" : "Asking price ($)";
    form.type.innerHTML = st.place ? st.place.units.map(u => `<option value="${esc(u.type)}">${esc(title(u.type))}</option>`).join("") : "";
    if (st.place) {
      const u = st.place.units[0];
      form.sqft.value = Math.round(u.sqm * SQFT);
      form.floor.max = (st.place.floors || 50) + (st.kind === "condo" ? 5 : 0);
    }
  };
  $$("#sKind button").forEach(b => b.onclick = () => {
    st.kind = b.dataset.k; st.place = null;
    $$("#sKind button").forEach(x => x.setAttribute("aria-pressed", x === b));
    $("#placeQ").value = ""; $("#placeRes").innerHTML = ""; $("#placeSel").textContent = "No block or project selected.";
    syncFields(); suggest();
  });
  $$("#sMode button").forEach(b => b.onclick = () => { mode = b.dataset.m; $$("#sMode button").forEach(x => x.setAttribute("aria-pressed", x === b)); syncFields(); suggest(); });
  $("#placeQ").oninput = () => {
    clearTimeout(timer);
    timer = setTimeout(async () => {
      const qv = $("#placeQ").value.trim();
      if (qv.length < 2) { $("#placeRes").innerHTML = ""; return; }
      const r = await api(`/api/places?kind=${st.kind}&q=${encodeURIComponent(qv)}`);
      const res = r.ok ? r.data.results : [];
      $("#placeRes").innerHTML = res.length ? res.map((p, i) => `<button type="button" class="chip-btn" data-i="${i}">${esc(p.label)}</button>`).join("") : `<span class="faint">No matches.</span>`;
      $$("#placeRes [data-i]").forEach(b => b.onclick = () => {
        st.place = res[+b.dataset.i];
        $("#placeSel").innerHTML = `Selected: <b>${esc(st.place.label)}</b>`;
        $("#placeRes").innerHTML = "";
        syncFields(); suggest();
      });
    }, 250);
  };
  const body = () => {
    const sqm = +form.sqft.value / SQFT;
    const b = { kind: st.kind, id: st.place?.id, sqm: sqm.toFixed(1) };
    if (st.kind === "hdb") Object.assign(b, { type: form.type.value, storey: form.floor.value });
    if (st.kind === "condo") b.floor = form.floor.value;
    if (st.kind === "landed") b.type = form.type.value;
    return b;
  };
  async function suggest() {
    const box = $("#suggest");
    if (!st.place || !form.sqft.value) { box.innerHTML = `<span class="faint">Choose a block or project and size to get a price suggestion.</span>`; return; }
    const r = await api("/api/value", body());
    if (!r.ok) { box.innerHTML = `<span class="err">${esc(r.data.error)}</span>`; return; }
    const v = r.data;
    if (mode === "rent") {
      box.innerHTML = `Estimated sale value <b>${fmt$(v.est)}</b>. At a typical ${st.kind === "hdb" ? "4–5%" : "3–4%"} gross yield, rent would be around
        <b>${fmt$(v.est * (st.kind === "hdb" ? 0.04 : 0.03) / 12)}–${fmt$(v.est * (st.kind === "hdb" ? 0.05 : 0.04) / 12)}</b>/month (rough guide; there's no rent model).`;
    } else {
      box.innerHTML = `<div class="faint">sg-home.com estimate</div><div style="font-size:24px;font-weight:700" class="num">${fmt$(v.est)}</div>
        <div class="faint">80% range ${fmtK(v.lo)} – ${fmtK(v.hi)} · $${Math.round(v.psm / SQFT).toLocaleString("en-SG")} psf</div>
        <p>Homes listed within about 5% of the estimate tend to look fairly priced to buyers: <b>${fmtK(v.est)}–${fmtK(v.est * 1.05)}</b>.
        <button type="button" class="btn small" id="usePrice">Use ${fmtK(v.est)}</button></p>
        ${v.warnings.map(w => `<div class="err">${esc(w)}</div>`).join("")}`;
      $("#usePrice").onclick = () => { form.price.value = v.est; };
    }
  }
  for (const n of ["sqft", "floor", "type"]) form[n].addEventListener("change", suggest);
  form.onsubmit = async e => {
    e.preventDefault();
    if (!st.place) { $("#sellMsg").innerHTML = `<span class="err">Choose a block or project first.</span>`; return; }
    const b = body();
    const payload = { kind: st.kind, id: st.place.id, mode, price: form.price.value, sqm: b.sqm, beds: form.beds.value, baths: form.baths.value,
      type: st.kind === "condo" ? null : form.type.value, floor: st.kind === "landed" ? null : form.floor.value,
      furnishing: form.furnishing.value, description: form.description.value, name: form.name.value, email: form.email.value };
    const r = await api("/api/listings", payload);
    if (!r.ok) { $("#sellMsg").innerHTML = `<span class="err">${esc(r.data.error)}</span>`; return; }
    addListings([r.data]);
    location.hash = `#/listing/${r.data.id}`;
    toast("Your listing is live");
  };
  syncFields();
  // Prefill from "List it on sg-home.com" on the valuation page: ?kind=&id=&sqft=&floor=&type=
  if (q.kind && VM[q.kind] && q.id) {
    loadSG().then(() => {
      const x = S.sgById[q.kind][q.id];
      if (!x || currentPath() !== "/sell") return;
      $(`#sKind [data-k="${q.kind}"]`).click();
      st.place = { id: x.id, label: placeName(q.kind, x), units: x.units.map(u => ({ type: u.type, sqm: u.sqm })), floors: x.floors };
      $("#placeSel").innerHTML = `Selected: <b>${esc(st.place.label)}</b>`;
      syncFields();
      if (q.sqft) form.sqft.value = q.sqft;
      if (q.floor) form.floor.value = q.floor;
      if (q.type && [...form.type.options].some(o => o.value === q.type)) form.type.value = q.type;
      suggest();
    });
  }
}

// ---------- boot ----------
function addListings(ls) {
  for (const l of ls) {
    if (S.byId[l.id]) continue;
    S.listings.unshift(l);
    S.byId[l.id] = l;
  }
}

Promise.all([
  fetch("/data/listings.json").then(r => r.json()), fetch("/data/agents.json").then(r => r.json()),
  fetch("/data/projects.json").then(r => r.json()), fetch("/data/trends.json").then(r => r.json()),
  fetch("/data/hero.json").then(r => r.json()), fetch("/data/areas.json").then(r => r.json()),
  api("/api/user-listings").catch(() => ({ ok: false })),
]).then(([L, agents, projects, trends, hero, areas, user]) => {
  S.hero = hero;
  S.areas = areas;
  S.meta = L.meta;
  S.listings = L.listings;
  S.listings.forEach(l => (S.byId[l.id] = l));
  if (user.ok) addListings(user.data.listings);
  agents.forEach(a => (S.agents[a.id] = a));
  S.projects = projects;
  projects.forEach(p => (S.projById[p.id] = p));
  S.trends = trends;
  compare = compare.filter(id => S.byId[id]);
  updateCounts();
  route();
}).catch(err => {
  $("#main").innerHTML = `<div class="wrap"><div class="empty" style="margin:40px 0">Couldn't load data. Please try again in a moment.<br><span class="faint">${esc(err)}</span></div></div>`;
});
